import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.DW1JcZt2.js";const f=JSON.parse('{"title":"World API SDK","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md"}'),s={name:"reference/index.md"};function o(i,t,n,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="world-api-sdk" tabindex="-1">World API SDK <a class="header-anchor" href="#world-api-sdk" aria-label="Permalink to &quot;World API SDK&quot;">​</a></h1><p>工作台扩展 API。</p><p>本文件是生产桥、SDK 类型和 API 文档共同使用的源码。 扩展运行时由宿主注入 workbench，不要在扩展包中复制桥接脚本。</p><h2 id="系统" tabindex="-1">系统 <a class="header-anchor" href="#系统" aria-label="Permalink to &quot;系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/AppAPI">AppAPI</a></td><td>工作台信息与能力查询。</td></tr><tr><td><a href="./classes/UIAPI">UIAPI</a></td><td>界面提示。</td></tr><tr><td><a href="./classes/CommandsAPI">CommandsAPI</a></td><td>扩展清单中声明的命令。</td></tr><tr><td><a href="./classes/Workbench">Workbench</a></td><td>扩展 API 根对象；生产环境通过全局 workbench 访问。</td></tr></tbody></table><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to &quot;页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/PagesAPI">PagesAPI</a></td><td>本扩展的独立页面。</td></tr></tbody></table><h2 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to &quot;资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/StorageAPI">StorageAPI</a></td><td>每扩展独立的本地 JSON 键值存储，不设置固定容量配额；使用本机可用磁盘与内存。</td></tr><tr><td><a href="./classes/ScenesAPI">ScenesAPI</a></td><td>本地场景资源。</td></tr><tr><td><a href="./classes/ComponentsAPI">ComponentsAPI</a></td><td>本地组件资源。</td></tr></tbody></table><h2 id="窗口" tabindex="-1">窗口 <a class="header-anchor" href="#窗口" aria-label="Permalink to &quot;窗口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/WindowAPI">WindowAPI</a></td><td>显式指定的已连接窗口。</td></tr></tbody></table><h2 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/AgentAPI">AgentAPI</a></td><td>内置 Agent；复用宿主模型配置，各扩展页面的任务与会话隔离。</td></tr></tbody></table><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./type-aliases/Params">Params</a></td><td>通用参数对象。</td></tr><tr><td><a href="./interfaces/FloatingOptions">FloatingOptions</a></td><td>-</td></tr><tr><td><a href="./type-aliases/Resource">Resource</a></td><td>场景、组件等资源的扩展字段。</td></tr><tr><td><a href="./type-aliases/Permission">Permission</a></td><td>扩展可声明的权限。</td></tr><tr><td><a href="./interfaces/CommandContext">CommandContext</a></td><td>-</td></tr><tr><td><a href="./interfaces/Entry">Entry</a></td><td>-</td></tr><tr><td><a href="./interfaces/ExtensionManifest">ExtensionManifest</a></td><td>-</td></tr><tr><td><a href="./type-aliases/AgentModel">AgentModel</a></td><td>模型公开信息，不含密钥和接口地址。</td></tr><tr><td><a href="./type-aliases/AgentState">AgentState</a></td><td>Agent 任务状态。</td></tr><tr><td><a href="./type-aliases/AgentEvent">AgentEvent</a></td><td>增量事件；seq 是任务内递增序号。</td></tr><tr><td><a href="./type-aliases/AgentStart">AgentStart</a></td><td>任务请求；不传 conversationId 则创建独立会话。</td></tr><tr><td><a href="./type-aliases/AgentJob">AgentJob</a></td><td>任务句柄。</td></tr><tr><td><a href="./type-aliases/AgentPoll">AgentPoll</a></td><td>任务查询结果。</td></tr><tr><td><a href="./type-aliases/AgentMessage">AgentMessage</a></td><td>调用方管理的消息。</td></tr><tr><td><a href="./type-aliases/AgentTurn">AgentTurn</a></td><td>单次模型采样；不执行工具，不注入工作台提示词。</td></tr><tr><td><a href="./type-aliases/AgentResponse">AgentResponse</a></td><td>单轮原始文本、原生工具调用及供应商用量。</td></tr><tr><td><a href="./type-aliases/AgentChat">AgentChat</a></td><td>单轮调用及流式回调。</td></tr><tr><td><a href="./type-aliases/AgentRun">AgentRun</a></td><td>自动轮询任务的参数。</td></tr><tr><td><a href="./type-aliases/APIMethod">APIMethod</a></td><td>方法权限与可用性。</td></tr><tr><td><a href="./type-aliases/APIDescription">APIDescription</a></td><td>宿主实际注册的接口清单。</td></tr><tr><td><a href="./type-aliases/HTTPMethod">HTTPMethod</a></td><td>支持的 HTTP 方法。</td></tr><tr><td><a href="./type-aliases/HTTPResponseType">HTTPResponseType</a></td><td>响应正文解码类型，默认 json；空 JSON 正文返回 null。</td></tr><tr><td><a href="./type-aliases/HTTPQueryValue">HTTPQueryValue</a></td><td>查询参数基础值，布尔值编码为 true/false，null 编码为空字符串，数组展开为重复参数。</td></tr><tr><td><a href="./interfaces/HTTPRequestOptions">HTTPRequestOptions</a></td><td>-</td></tr><tr><td><a href="./type-aliases/HTTPResponse">HTTPResponse</a></td><td>HTTP 响应。url 为最终地址，ok 表示 2xx；header 名称小写，同名 header 用换行分隔。自动解压 gzip/deflate，bytes 是解压后正文长度；base64 正文也是解压后的实体内容。HTTP 4xx/5xx 正常返回；网络、TLS、超时、解压及正文格式错误会拒绝 Promise。</td></tr><tr><td><a href="./type-aliases/SQLiteValue">SQLiteValue</a></td><td>SQLite 值；大整数用十进制字符串封装，BLOB 用纯 Base64。结果布尔值以整数 0/1 返回，超出 JS 安全范围的整数返回 integer 对象。</td></tr><tr><td><a href="./type-aliases/SQLiteParams">SQLiteParams</a></td><td>位置参数或命名绑定参数；禁止拼接不可信输入到 SQL。</td></tr><tr><td><a href="./type-aliases/SQLiteStatement">SQLiteStatement</a></td><td>单条 SQL 及绑定值。</td></tr><tr><td><a href="./type-aliases/SQLiteOptions">SQLiteOptions</a></td><td>操作超时，默认 10000 毫秒，可设置为 1–60000，包含等待锁时间；长查询请分页。</td></tr><tr><td><a href="./type-aliases/SQLiteWriteResult">SQLiteWriteResult</a></td><td>本语句影响行数（包含触发器）和 INSERT 行 ID，其他语句为 null。</td></tr><tr><td><a href="./type-aliases/SQLiteInfo">SQLiteInfo</a></td><td>数据库信息；bytes 包含当前 WAL/SHM 文件，version 由 migrate 管理。</td></tr><tr><td><a href="./type-aliases/SQLiteVirtualModule">SQLiteVirtualModule</a></td><td>可创建的内置模块；FTS5 默认 unicode61 分词，RTree 支持 1–5 维范围索引。不接受原生模块、外部 content 表或自定义 tokenizer。</td></tr><tr><td><a href="./type-aliases/SQLiteVirtualTableOptions">SQLiteVirtualTableOptions</a></td><td>虚拟表定义。表名和列名统一小写，只允许 1–64 位 ASCII 字母、数字、下划线，不能以数字开头，禁止 sqlite_、_<em>world</em> 前缀；列名不能重复或与表同名。FTS5 不允许 rank/rowid 列名。RTree columns 为 ID 列加 1–5 对 min/max 列，共 3、5、7、9 或 11 列。</td></tr><tr><td><a href="./type-aliases/BrowserTab">BrowserTab</a></td><td>工作台页面标识；文档种类仅包含本扩展创建的网页。</td></tr><tr><td><a href="./type-aliases/BrowserTimeout">BrowserTimeout</a></td><td>等待预算，默认 10000 毫秒，0 表示立即检查，最大 60000 毫秒。页面关闭、不可用或权限失效时拒绝 Promise。</td></tr><tr><td><a href="./type-aliases/BrowserNavigation">BrowserNavigation</a></td><td>导航等待条件，默认 load；none 只等待浏览器接受导航，不表示页面加载完成。</td></tr><tr><td><a href="./type-aliases/BrowserPageInfo">BrowserPageInfo</a></td><td>当前页面状态；框架信息中的历史标志仍属于整个 Tab。</td></tr><tr><td><a href="./type-aliases/BrowserSelector">BrowserSelector</a></td><td>可组合的元素条件。selector 是 CSS；text/name 默认包含匹配，exact=true 精确匹配；role/name 支持常见原生控件和显式 ARIA 属性，不等价于完整无障碍树算法。nth 从 0 开始；未指定时动作要求唯一匹配。定位器每次操作重新解析，不缓存失效节点。</td></tr><tr><td><a href="./type-aliases/BrowserRect">BrowserRect</a></td><td>网页 CSS 像素矩形。</td></tr><tr><td><a href="./type-aliases/BrowserElement">BrowserElement</a></td><td>元素状态。</td></tr><tr><td><a href="./type-aliases/BrowserClick">BrowserClick</a></td><td>点击选项；默认左键，等待可见、启用、位置稳定且命中点未被遮挡。</td></tr><tr><td><a href="./type-aliases/BrowserActionResult">BrowserActionResult</a></td><td>浏览器已执行输入或元素操作；不代表服务端业务保存成功，业务结果需继续等待或读取。</td></tr><tr><td><a href="./type-aliases/BrowserScreenshot">BrowserScreenshot</a></td><td>截图选项；默认 png，quality 为 0–100，仅用于有损格式。fullPage 与 clip 不同时使用。</td></tr><tr><td><a href="./type-aliases/BrowserProtocolEvent">BrowserProtocolEvent</a></td><td>页面 DevTools 事件。</td></tr><tr><td><a href="./type-aliases/BrowserEventBatch">BrowserEventBatch</a></td><td>事件增量；cursor 用于下次读取，dropped 非零表示消费者落后造成事件丢失。</td></tr><tr><td><a href="./functions/getWorkbench">getWorkbench</a></td><td>获取宿主已注入的根对象；不会安装第二份桥。</td></tr></tbody></table><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/SQLiteAPI">SQLiteAPI</a></td><td>本扩展的 SQLite 数据库目录。需在清单声明 storage.sqlite。数据库名不接受路径，统一转为小写，支持 1–64 位英文字母、数字、下划线、短横线；拒绝 Windows 保留名称。扩展升级及卸载保留数据。</td></tr><tr><td><a href="./classes/SQLiteDatabase">SQLiteDatabase</a></td><td>由 sqlite.open 返回的数据库对象。WAL 模式，同一数据库操作串行化，SQL 在宿主后台执行，不阻塞界面。禁止外部路径、ATTACH/DETACH、设置 PRAGMA、自定义事务控制、原生扩展及临时表；虚拟表通过封装接口创建和删除，使用 batch/migrate 管理普通写入事务，不提供跨调用连接状态。FTS5 库允许只读 data_version PRAGMA 供模块内部同步，其他 PRAGMA 仍拒绝。关闭页面、禁用或升级扩展后句柄失效，再次打开即可恢复持久化数据。</td></tr></tbody></table><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/FilesAPI">FilesAPI</a></td><td>用户主动选择路径的文件导出。</td></tr></tbody></table><h2 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/BrowserAPI">BrowserAPI</a></td><td>网页打开与自动化入口；复用工作台原生浏览器，不向远端网页暴露宿主或扩展凭证。</td></tr><tr><td><a href="./classes/BrowserPage">BrowserPage</a></td><td>工作台原生 WebView2 页面。浏览器行为通过宿主的页面协议与真实输入通道执行，不附带另一套浏览器或驱动。框选编辑中的页面可能隔离用户输入；自动化前由调用方结束不兼容的编辑任务。每个对象固定到 tabId，不隐式切换活动页。</td></tr><tr><td><a href="./classes/BrowserLocator">BrowserLocator</a></td><td>页面元素定位器。每次动作重新查询目标，支持延迟出现及 DOM 重建；多匹配需使用 nth 明确目标。普通点击、悬停和输入使用浏览器原生输入协议；selectOption 使用原生 select 的值及 input/change 事件，不调用网页的 element.click。</td></tr><tr><td><a href="./classes/BrowserSubscription">BrowserSubscription</a></td><td>目标页面的 DevTools 事件订阅。使用结束后 unsubscribe；可在插件自管循环中读取网络、控制台或 Fetch 拦截事件。需同时声明 browser.automation 与 browser.devtools。</td></tr></tbody></table><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/NetworkAPI">NetworkAPI</a></td><td>经工作台宿主执行的 HTTP/HTTPS 请求；不受浏览器 CORS 限制，需清单声明 network 权限。每次请求独立，不共享工作台登录态，不持久化服务器 Cookie。HTTPS 保持系统默认的证书和主机名校验，不开放关闭校验的选项。响应整体缓冲，无固定正文容量配额，受本机内存和消息传输资源约束；不提供流式响应。</td></tr></tbody></table><h2 id="飞书" tabindex="-1">飞书 <a class="header-anchor" href="#飞书" aria-label="Permalink to &quot;飞书&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/FeishuAPI">FeishuAPI</a></td><td>飞书 OpenAPI；复用工作台 OAuth 登录，无需 CLI，不向扩展返回凭证。</td></tr></tbody></table>',25)])])}const p=e(s,[["render",o]]);export{f as __pageData,p as default};
